// GENERATED by scripts/export-playwright.sh — Playwright 默认快捷登录
import { chromium, type BrowserContext, type Page } from '@playwright/test';
import fs from 'node:fs';
import path from 'node:path';

const BASE = process.env.WI_BASE_URL || "http://127.0.0.1:8765";
const AUTH_FILE = path.join(__dirname, '.auth', 'storage-state.json');
const LOGIN = {
  "probePath": "/english/",
  "loginDomain": "",
  "quickSelectors": [],
  "usernameSelector": "",
  "passwordSelector": "",
  "codeSelector": "",
  "submitSelectors": [],
  "usernameEnv": "WI_LOGIN_USERNAME",
  "passwordEnv": "WI_LOGIN_PASSWORD",
  "codeEnv": "WI_LOGIN_CODE"
};
const LOGIN_TEXT = /快速登录|一键登录|确认登录|继续|SSO|Continue|Sign in with|微信|企业微信|企微|IOA|太湖|Google/i;

const resolveURL = (value: string) => /^https?:\/\//i.test(value)
  ? value
  : `${BASE.replace(/\/$/, '')}/${value.replace(/^\//, '')}`;

async function visible(page: Page, selector: string): Promise<boolean> {
  if (!selector) return false;
  try {
    return await page.locator(selector).first().isVisible();
  } catch {
    return false;
  }
}

async function authenticated(page: Page): Promise<boolean> {
  await page.waitForTimeout(800);
  const url = page.url();
  let host = '';
  try { host = new URL(url).hostname; } catch {}
  const pathLooksLikeLogin = /(^|[\/#])(login|signin|sign-in|sso|oauth|cas|passport)([\/?#]|$)/i.test(url);
  const configuredLoginHost = LOGIN.loginDomain && host.includes(LOGIN.loginDomain);
  const passwordVisible = await visible(page, 'input[type="password"]');
  return !pathLooksLikeLogin && !configuredLoginHost && !passwordVisible;
}

async function clickSelector(page: Page, selector: string): Promise<boolean> {
  try {
    const target = page.locator(selector).first();
    if (!(await target.isVisible())) return false;
    await target.click();
    return true;
  } catch {
    return false;
  }
}

async function fillFirst(page: Page, selectors: string[], value: string | undefined): Promise<boolean> {
  if (!value) return false;
  for (const selector of selectors.filter(Boolean)) {
    try {
      const target = page.locator(selector).first();
      if (await target.isVisible()) {
        await target.fill(value);
        return true;
      }
    } catch {}
  }
  return false;
}

async function newestPage(context: BrowserContext, current: Page): Promise<Page> {
  await current.waitForTimeout(1000);
  const pages = context.pages();
  return pages[pages.length - 1] || current;
}

async function attemptLogin(context: BrowserContext, initialPage: Page): Promise<Page> {
  let page = initialPage;
  for (let round = 0; round < 3; round += 1) {
    if (await authenticated(page)) return page;

    let acted = false;
    for (const selector of LOGIN.quickSelectors) {
      if (await clickSelector(page, selector)) {
        acted = true;
        break;
      }
    }

    const username = process.env[LOGIN.usernameEnv];
    const password = process.env[LOGIN.passwordEnv];
    const code = process.env[LOGIN.codeEnv];
    const filledUser = await fillFirst(page, [
      LOGIN.usernameSelector,
      'input[autocomplete="username"]',
      'input[type="email"]',
      'input[name*="user" i]',
      'input[name*="account" i]',
    ], username);
    const filledPassword = await fillFirst(page, [
      LOGIN.passwordSelector,
      'input[autocomplete="current-password"]',
      'input[type="password"]',
    ], password);
    const filledCode = await fillFirst(page, [
      LOGIN.codeSelector,
      'input[autocomplete="one-time-code"]',
      'input[name*="code" i]',
      'input[name*="otp" i]',
    ], code);
    if (filledUser || filledPassword || filledCode) {
      acted = true;
      const submitSelectors = [
        ...LOGIN.submitSelectors,
        'button[type="submit"]',
        'input[type="submit"]',
      ];
      for (const selector of submitSelectors) {
        if (await clickSelector(page, selector)) break;
      }
    }

    if (!acted) {
      try {
        const candidate = page.locator('button, a, [role="button"]').filter({ hasText: LOGIN_TEXT }).first();
        if (await candidate.isVisible()) {
          await candidate.click();
          acted = true;
        }
      } catch {}
    }
    if (!acted) break;

    page = await newestPage(context, page);
    try { await page.waitForLoadState('domcontentloaded', { timeout: 10000 }); } catch {}
    await page.waitForTimeout(1500);
  }
  return page;
}

export default async function globalSetup() {
  fs.mkdirSync(path.dirname(AUTH_FILE), { recursive: true });
  const browser = await chromium.launch({ headless: process.env.WI_PW_LOGIN_HEADED !== '1' });
  const context = await browser.newContext(fs.existsSync(AUTH_FILE) ? { storageState: AUTH_FILE } : {});
  let page = await context.newPage();
  try {
    await page.goto(resolveURL(LOGIN.probePath), { waitUntil: 'domcontentloaded', timeout: 30000 });
    if (!(await authenticated(page))) page = await attemptLogin(context, page);
    if (!(await authenticated(page))) {
      throw new Error(`[WI_PW_LOGIN_FAILED] 快捷登录未进入主流程：${page.url()}；Agent 应切换 CDP 并重复自动认证`);
    }
    await context.storageState({ path: AUTH_FILE });
  } finally {
    await browser.close();
  }
}
